// Keep per-page search and scroll in this tab; no business records are changed.
const pageViews=new Map(),navigationTrail=[];
let renderedRoute='';
const parentPages={account:['accounts','거래처 목록'],order:['orders','주문 목록'],transaction:['transactions','거래 목록'],product:['products','품목 목록'],task:['tasks','할 일 목록'],quote:['quotes','견적 목록']};
function navigationLinks(){
 const parent=parentPages[route().split('/')[0]];if(!parent)return '';
 const source=navigationTrail.at(-2);
 return `<nav class="detail-navigation" aria-label="상세 화면 이동"><a href="#${parent[0]}" data-list-return>← ${parent[1]}</a>${source&&source!==parent[0]?`<a href="#${esc(source)}" data-context-return>이전 화면으로</a>`:''}</nav>`;
}
function rememberPage(){if(renderedRoute&&renderedRoute===route())pageViews.set(renderedRoute,{filter,scroll:window.scrollY||0});}
function syncNavigation(){
 const next=route();if(next===renderedRoute)return null;
 if(renderedRoute){const old=pageViews.get(renderedRoute)||{};pageViews.set(renderedRoute,{...old,filter});}
 const index=navigationTrail.lastIndexOf(next);
 if(index>=0)navigationTrail.splice(index+1);else navigationTrail.push(next);
 renderedRoute=next;const saved=pageViews.get(next)||{filter:'',scroll:0};filter=saved.filter;return saved.scroll;
}
window.addEventListener('scroll',rememberPage,{passive:true});
const query=()=>`?workspace=${workspace}`;
async function api(path,body){
 return demoApi(path,body);
}
async function legacyApi(path,body){
 // Presentation-only restriction: the server's existing authentication and permissions stay unchanged.
 if(isMobile()&&body!==undefined&&!(path==='/api/workflow'&&body.action==='erp.task.save')&&!['/api/guide/ask','/api/auth/logout'].includes(path)){
  showMobileRestriction();throw Error('이 업무는 PC에서 이용해 주세요.');
 }
 const r=await fetch(path+query(),body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(r.status===401){location.replace('/login'+location.hash);throw Error('다시 로그인해 주세요.');}const result=await r.json();if(!r.ok)throw Error(result.error||'요청을 완료하지 못했어요.');return result;}
async function reload(){const r=await api('/api/state');state=r.state;revision=r.revision;lookup.refresh(dialog);render();}
let refreshing=false;
async function refreshFromServer(){
 if(!state||busy||refreshing)return;refreshing=true;const startedRevision=revision;
 try{const r=await api('/api/state');if(!busy&&revision===startedRevision&&r.revision>=revision){state=r.state;revision=r.revision;lookup.refresh(dialog);render();}}
 catch{}finally{refreshing=false;}
}
window.addEventListener('focus',refreshFromServer);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshFromServer();});
async function quickAccount(data){
 await refreshFromServer();
 if(state.ledgerVersion===2){const r=await runWorkflow('erp.account.save',data);return r.recordId;}
 const ident=id('account');await commit(s=>s.accounts.push({...data,id:ident}));return ident;
}
async function commit(change,message='저장했어요.'){if(busy)throw Error('저장 중입니다. 잠시 기다려 주세요.');busy=true;const next=structuredClone(state);try{change(next);const r=await api('/api/state',{state:next,revision});state=next;revision=r.revision;render();if(message)toast(message);}finally{busy=false;}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
