  if(supported)erp.bind();
  if(supported||current==='guide'){lastRestrictedRoute='';mobileRestriction?.close();}
  else if(lastRestrictedRoute!==route()){lastRestrictedRoute=route();showMobileRestriction();}
  if(restoreScroll!==null)window.scrollTo?.(0,restoreScroll);
