function passwordForm(){modal('비밀번호 변경',`<div class="form-grid">${field('현재 비밀번호','currentPassword','','password','required autocomplete="current-password" maxlength="256"')}${field('새 비밀번호 · 12자 이상','password','','password','required autocomplete="new-password" minlength="12" maxlength="256"')}</div>`,'변경',async f=>{await api('/api/auth/password',Object.fromEntries(f));toast('비밀번호를 변경했어요. 다른 기기의 로그인은 해제돼요.');});}
async function cloudBackup(){
 if(busy)return;busy=true;toast('백업을 준비하고 있어요. 잠시 기다려 주세요.');
 try{
  const snapshot=await api('/api/backup-manifest');
  const {zipSync,strToU8}=await import('./vendor/fflate.js');
  const files={'growth-backup.json':strToU8(JSON.stringify(snapshot,null,2))};let total=files['growth-backup.json'].length;
  for(const doc of snapshot.state.documents){
   if(!/^doc-[a-f0-9]+\.(xlsx|pdf)$/.test(doc.storedName))throw Error('원본 파일 정보를 확인해 주세요.');
   const response=await fetch(`/api/documents/${encodeURIComponent(doc.id)}/file${query()}`);
   if(!response.ok)throw Error('일부 문서를 내려받지 못했어요. 다시 백업해 주세요.');
   const bytes=new Uint8Array(await response.arrayBuffer());total+=bytes.length;
   if(total>100*1024*1024)throw Error('전체 백업이 100MB를 넘습니다. 관리자에게 서버 백업을 요청해 주세요.');
   files['documents/'+doc.storedName]=bytes;
  }
  const url=URL.createObjectURL(new Blob([zipSync(files,{level:0})],{type:'application/zip'}));
  const a=document.createElement('a');a.href=url;a.download=`growth-${workspace}-${today()}.zip`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('백업 파일을 내려받았어요.');
 }finally{busy=false;}
}

// Due-date alerts refresh at the Korean business-day boundary without duplicating task records.
let alertDay=today();
const dueTimer=setInterval(()=>{const day=today();if(day!==alertDay){alertDay=day;if(state?.ledgerVersion===2)render();}},60000);
dueTimer.unref?.();
